// Package facade serves the HTTP/JSON form of a gRPC service, generated by gRPC-Gateway from the
// proto's `google.api.http` rules, at the application boundary.
package facade

import (
	"context"
	"errors"
	"net/http"
	"time"

	"github.com/agentydragon/ducktape/agentplane/observability"
	"github.com/grpc-ecosystem/grpc-gateway/v2/runtime"
	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials/insecure"
)

// Registration is the generated `Register<Service>HandlerFromEndpoint`.
type Registration func(ctx context.Context, mux *runtime.ServeMux, endpoint string, opts []grpc.DialOption) error

// NewHandler forwards each HTTP request for the registered services to the gRPC server at target.
// The target may be local to the process or a configured downstream service; every call still passes
// through the servicer's own authentication and interceptors. The gateway sends the `Authorization`
// header on as `authorization` metadata, the form the servicers read. Retries are disabled because
// registrations include mutations. Server-streaming methods answer newline-delimited JSON, one
// `{"result": ...}` object per message. unaryTimeout bounds unary calls; zero leaves unary calls
// under their servicer's own bounds. Streaming calls always use only the HTTP request context. The
// connections close when ctx ends.
func NewHandler(ctx context.Context, target string, unaryTimeout time.Duration, registrations ...Registration) (http.Handler, error) {
	if unaryTimeout < 0 {
		return nil, errors.New("unary timeout must not be negative")
	}
	mux := runtime.NewServeMux()
	for _, register := range registrations {
		dialOptions := []grpc.DialOption{
			observability.GRPCClientOption(), grpc.WithTransportCredentials(insecure.NewCredentials()), grpc.WithDisableRetry(),
		}
		if unaryTimeout > 0 {
			dialOptions = append(dialOptions, grpc.WithUnaryInterceptor(unaryTimeoutInterceptor(unaryTimeout)))
		}
		if err := register(ctx, mux, target, dialOptions); err != nil {
			return nil, err
		}
	}
	return mux, nil
}

func unaryTimeoutInterceptor(timeout time.Duration) grpc.UnaryClientInterceptor {
	return func(ctx context.Context, method string, request, response any, connection *grpc.ClientConn, invoker grpc.UnaryInvoker, options ...grpc.CallOption) error {
		requestContext, cancel := context.WithTimeout(ctx, timeout)
		defer cancel()
		return invoker(requestContext, method, request, response, connection, options...)
	}
}
